#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stdout)]
use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, extract};
use caliper_docgen_semantic::{SemanticRequest, resolve, targets_of};
use camino::Utf8PathBuf;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = Utf8PathBuf::from(&args[1]);
    let tsc = Utf8PathBuf::from(&args[2]);
    let tsconfig = Utf8PathBuf::from(&args[3]);
    let out = Utf8PathBuf::from(&args[4]);
    let options = PipelineOptions {
        src_dirs: vec![src.clone()],
        load_dependencies: true,
        html_attributes: HtmlAttributeMode::Curated,
        ..Default::default()
    };
    let output = extract(&options);
    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(&src).unwrap()).unwrap();
    let mut request = SemanticRequest::new(root, targets_of(&output));
    request.tsconfig = Some(tsconfig);
    request.tsc_path = Some(tsc);
    let outcome = resolve(request);
    let mut lines = Vec::new();
    for component in &outcome.components {
        for prop in &component.props {
            lines.push(format!("{}.{}: {}", component.display_name, prop.name, serde_json::to_string(&prop.prop_type).unwrap()));
        }
    }
    std::fs::write(out, lines.join("\n")).unwrap();
    println!("{} props", lines.len());
}
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stdout)]
use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, extract};
use caliper_docgen_semantic::{SemanticRequest, resolve, targets_of};
use camino::Utf8PathBuf;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = Utf8PathBuf::from(&args[1]);
    let tsc = Utf8PathBuf::from(&args[2]);
    let tsconfig = Utf8PathBuf::from(&args[3]);
    let out = Utf8PathBuf::from(&args[4]);
    let options = PipelineOptions {
        src_dirs: vec![src.clone()],
        load_dependencies: true,
        html_attributes: HtmlAttributeMode::Curated,
        ..Default::default()
    };
    let output = extract(&options);
    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(&src).unwrap()).unwrap();
    let mut request = SemanticRequest::new(root, targets_of(&output));
    request.tsconfig = Some(tsconfig);
    request.tsc_path = Some(tsc);
    request.record_to = Some(out.clone());
    let started = std::time::Instant::now();
    let outcome = resolve(request);
    println!("resolved {} in {:?}", outcome.components.len(), started.elapsed());
    let calls: Vec<serde_json::Value> = serde_json::from_str(&std::fs::read_to_string(&out).unwrap()).unwrap();
    let mut counts = std::collections::BTreeMap::new();
    for call in &calls {
        *counts.entry(call["method"].as_str().unwrap().to_string()).or_insert(0u64) += 1;
    }
    println!("total {} {counts:?}", calls.len());
}
