1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which instantiations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. A handle is also what tells one instantiation from
9	//! another while a type is being expanded (`Box<Box<string>>` is two instantiations of one declaration): only its
10	//! equality is read, inside one conversion, so the answer does not depend on the numbers. The recursion marker that
11	//! results is named by the declaration (the alias or interface) and holds no handle.
12	//!
13	//! Every descent into the parts of a type (members, properties, elements, holes) passes [`Converter::enter`], which
14	//! decides before anything is fetched or converted whether the type is an enclosing instantiation (a back-reference),
15	//! sits too deep, or is too wide.
16	//!
17	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
18	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
19	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
20	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type. A dependency's
21	//! union of literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
22	//! [`PropType::Truncated`], never the checker's text standing in as a name.
23	
24	use std::future::Future;
25	use std::hash::{Hash, Hasher};
26	use std::pin::Pin;
27	use std::sync::atomic::{AtomicU64, Ordering};
28	use std::sync::{Arc, Mutex};
29	
30	use caliper_docgen_core::types::semantic::{degraded_type, unresolved_type};
31	use caliper_docgen_core::types::{
32	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
33	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
34	};
35	use rustc_hash::{FxHashMap, FxHasher};
36	
37	use crate::printed::{Marker, SignatureMarkers, signature_markers, tuple_labels};
38	use crate::rpc::{
39	    CallError, CompactSymbol, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, TypeInfo, flag,
40	};
41	
42	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
43	const MAX_DEPTH: u8 = 5;
44	/// The most properties an object type lists at the top (a prop's own type) and below it.
45	const MAX_FIELDS: [usize; 2] = [100, 40];
46	/// The most members a union or intersection lists at the top and below it.
47	const MAX_MEMBERS: [usize; 2] = [500, 120];
48	
49	/// What a descent found at [`Converter::enter`].
50	enum Gate<T> {
51	    /// The type is not expanded: it is a back-reference, or a cap cut it.
52	    Stop(PropType),
53	    /// The parts of the type, and the context to convert them in.
54	    Open { parts: T, inner: Cx },
55	}
56	
57	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
58	
59	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
60	/// checker's type handle) enclose it, sorted so that the same set is the same key whatever path led to it.
61	#[derive(Debug, Clone, Default)]
62	pub(crate) struct Cx {
63	    depth: u8,
64	    enclosing: Arc<Vec<u64>>,
65	}
66	
67	impl Cx {
68	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
69	    /// and passes [`Converter::enter`] if it has parts.
70	    fn argument(&self) -> Cx {
71	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone() }
72	    }
73	
74	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
75	    /// only a name can be pointed back to.
76	    fn below(&self, instance: Option<u64>) -> Cx {
77	        let mut enclosing = self.enclosing.clone();
78	        if let Some(id) = instance
79	            && let Err(at) = enclosing.binary_search(&id)
80	        {
81	            let mut grown = (*enclosing).clone();
82	            grown.insert(at, id);
83	            enclosing = Arc::new(grown);
84	        }
85	        Cx { depth: self.depth.saturating_add(1), enclosing }
86	    }
87	
88	    fn encloses(&self, id: u64) -> bool {
89	        self.enclosing.binary_search(&id).is_ok()
90	    }
91	
92	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
93	        limits[usize::from(self.depth > 0).min(N - 1)]
94	    }
95	
96	    fn fingerprint(&self) -> u64 {
97	        let mut hasher = FxHasher::default();
98	        self.enclosing.hash(&mut hasher);
99	        hasher.finish()
100	    }
101	}
102	
103	/// What declares a type: the alias it was written through, else its interface or class.
104	#[derive(Debug, Clone)]
105	struct Origin {
106	    name: String,
107	    /// The declaring file as the checker keys it (lower-cased path).
108	    file: String,
109	    alias: bool,
110	}
111	
112	impl Origin {
113	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
114	        let declaration = symbol.declarations.first().map(String::as_str);
115	        Origin {
116	            name: symbol.name.clone(),
117	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
118	            alias,
119	        }
120	    }
121	
122	    fn in_dependency(&self) -> bool {
123	        self.file.contains("/node_modules/")
124	    }
125	
126	    fn in_lib(&self) -> bool {
127	        let name = self.file.rsplit('/').next().unwrap_or("");
128	        name.starts_with("lib.") && name.ends_with(".d.ts")
129	    }
130	
131	    fn in_react(&self) -> bool {
132	        self.file.contains("/@types/react/")
133	    }
134	
135	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
136	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
137	    fn is_boundary(&self) -> bool {
138	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
139	        if self.in_lib() { !self.alias } else { self.in_dependency() }
140	    }
141	
142	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
143	    fn react_terminal(&self) -> Option<PropType> {
144	        if !self.in_react() {
145	            return None;
146	        }
147	        match (self.name.as_str(), self.alias) {
148	            ("ReactNode", true) | ("ReactElement" | "Element", false) => Some(PropType::ReactNode),
149	            ("ElementType", true) => Some(PropType::ElementType),
150	            ("CSSProperties", false) => Some(PropType::CssProperties),
151	            _ => None,
152	        }
153	    }
154	}
155	
156	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
157	pub(crate) fn declared_in(declaration: &str) -> &str {
158	    declaration.splitn(3, '.').nth(2).unwrap_or("")
159	}
160	
161	type Memo = Mutex<FxHashMap<(u64, u8, u64), PropType>>;
162	
163	#[derive(Default)]
164	struct State {
165	    /// Conversions by (type handle, depth, enclosing instantiations). The handles are valid inside this snapshot only.
166	    memo: Memo,
167	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
168	    /// By (type handle, whether printed expanded: see [`Rpc::type_to_string_expanded`]).
169	    printed: Mutex<FxHashMap<(u64, bool), String>>,
170	    hits: AtomicU64,
171	    misses: AtomicU64,
172	}
173	
174	#[derive(Clone)]
175	pub(crate) struct Converter {
176	    rpc: Arc<Rpc>,
177	    state: Arc<State>,
178	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
179	    reverse: bool,
180	}
181	
182	impl Converter {
183	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
184	        Self { rpc, state: Arc::new(State::default()), reverse }
185	    }
186	
187	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
188	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
189	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
190	        let order: Box<dyn Iterator<Item = usize> + Send> =
191	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
192	        for index in order {
193	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
194	                *slot = Some(self.convert(info, cx).await?);
195	            }
196	        }
197	        Ok(slots.into_iter().flatten().collect())
198	    }
199	
200	    /// Memo hits and misses so far, for the debug line.
201	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
202	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
203	    }
204	
205	    /// The own types of a component's props, from the top.
206	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
207	        self.convert_all(infos, &Cx::default()).await
208	    }
209	
210	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
211	        Box::pin(async move {
212	            let key = (info.id, cx.depth, cx.fingerprint());
213	            if let Some(hit) = self.state.memo.lock().ok().and_then(|memo| memo.get(&key).cloned()) {
214	                self.state.hits.fetch_add(1, Ordering::Relaxed);
215	                return Ok(hit);
216	            }
217	            self.state.misses.fetch_add(1, Ordering::Relaxed);
218	            let converted = self.uncached(info, cx).await?;
219	            if let Ok(mut memo) = self.state.memo.lock() {
220	                memo.insert(key, converted.clone());
221	            }
222	            Ok(converted)
223	        })
224	    }
225	
226	    async fn uncached(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
227	        if info.is_error() {
228	            return Ok(unresolved_type(self.display(info.id).await?));
229	        }
230	        if let Some(simple) = simple(info) {
231	            return Ok(simple);
232	        }
233	        let flags = info.flags;
234	        if flags & flag::TYPE_PARAMETER != 0 {
235	            return self.type_parameter(info).await;
236	        }
237	        if flags & (flag::STRING_LITERAL | flag::NUMBER_LITERAL | flag::BIG_INT_LITERAL) != 0 {
238	            return self.literal(info).await;
239	        }
240	        if flags & flag::BOOLEAN_LITERAL != 0 {
241	            return Ok(PropType::BoolLiteral(self.boolean_value(info).await?));
242	        }
243	        if flags & flag::UNIQUE_ES_SYMBOL != 0 {
244	            let name = self.rpc.symbol_of_type(info.id).await?.map(|symbol| symbol.name);
245	            return Ok(match name {
246	                Some(name) => PropType::UniqueSymbol { name: name.into() },
247	                None => named(self.display(info.id).await?, Vec::new()),
248	            });
249	        }
250	        if flags & flag::TEMPLATE_LITERAL != 0 {
251	            return self.template(info, cx).await;
252	        }
253	        // `Uppercase<string>` and its siblings: a name, since there is no shape to expand.
254	        if flags & flag::STRING_MAPPING != 0 {
255	            return Ok(named(self.display(info.id).await?, Vec::new()));
256	        }
257	        // Types the checker could not resolve because a type parameter is still open.
258	        if flags & (flag::CONDITIONAL | flag::INDEXED_ACCESS | flag::INDEX | flag::SUBSTITUTION) != 0 {
259	            let text = self.display(info.id).await?;
260	            let reason = if flags & flag::CONDITIONAL != 0 {
261	                OpaqueReason::ConditionalType
262	            } else if flags & flag::INDEXED_ACCESS != 0 {
263	                OpaqueReason::IndexedAccess { expression: text.clone() }
264	            } else {
265	                OpaqueReason::UnsupportedExpression
266	            };
267	            return Ok(degraded_type(text, reason));
268	        }
269	        if flags & flag::UNION != 0 {
270	            return self.union(info, cx).await;
271	        }
272	        if flags & flag::INTERSECTION != 0 {
273	            return self.intersection(info, cx).await;
274	        }
275	        if flags & flag::OBJECT != 0 {
276	            return self.object(info, cx).await;
277	        }
278	        Ok(named(self.display(info.id).await?, Vec::new()))
279	    }
280	
281	    /// How the checker prints the type; only ever a name for display, a truncated type's text, or the source of the two
282	    /// facts in [`crate::printed`].
283	    async fn display(&self, id: u64) -> Result<String, CallError> {
284	        self.printed(id, false).await
285	    }
286	
287	    /// How the checker prints the type with an alias at the top expanded and nothing cut short: the text a signature's
288	    /// parameter markers are read from, since the alias's name states no parameter list.
289	    async fn display_expanded(&self, id: u64) -> Result<String, CallError> {
290	        self.printed(id, true).await
291	    }
292	
293	    async fn printed(&self, id: u64, expanded: bool) -> Result<String, CallError> {
294	        let key = (id, expanded);
295	        if let Some(text) = self.state.printed.lock().ok().and_then(|printed| printed.get(&key).cloned()) {
296	            return Ok(text);
297	        }
298	        let text =
299	            if expanded { self.rpc.type_to_string_expanded(id).await? } else { self.rpc.type_to_string(id).await? };
300	        if let Ok(mut printed) = self.state.printed.lock() {
301	            printed.insert(key, text.clone());
302	        }
303	        Ok(text)
304	    }
305	
306	    /// The alias a type was written through, when it has one.
307	    async fn alias_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
308	        match &info.alias_symbol {
309	            Some(alias) => self.origin_of(alias, true, info.id).await,
310	            None => Ok(None),
311	        }
312	    }
313	
314	    /// What declares the type, when it has a name of its own: an alias, or an interface, class or instantiation of one.
315	    async fn origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
316	        if info.alias_symbol.is_some() {
317	            return self.alias_origin(info).await;
318	        }
319	        if info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0 {
320	            return self.symbol_origin(info).await;
321	        }
322	        Ok(None)
323	    }
324	
325	    /// The interface or class a type is, whatever alias it was written through.
326	    async fn symbol_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
327	        match &info.symbol {
328	            Some(symbol) => self.origin_of(symbol, false, info.id).await,
329	            None => Ok(None),
330	        }
331	    }
332	
333	    /// The declaration behind a symbol, asked once per symbol however many types refer to it.
334	    async fn origin_of(&self, symbol: &CompactSymbol, alias: bool, type_id: u64) -> Result<Option<Origin>, CallError> {
335	        let key = (alias, symbol.clone());
336	        if let Some(known) = self.state.origins.lock().ok().and_then(|origins| origins.get(&key).cloned()) {
337	            return Ok(known);
338	        }
339	        let found =
340	            if alias { self.rpc.alias_symbol(type_id).await? } else { self.rpc.symbol_of_type(type_id).await? };
341	        // `__type` and `__object` are the checker's names for a type that has none.
342	        let found = found.map(|symbol| Origin::of(&symbol, alias)).filter(|origin| !origin.name.starts_with("__"));
343	        if let Ok(mut origins) = self.state.origins.lock() {
344	            origins.insert(key, found.clone());
345	        }
346	        Ok(found)
347	    }
