349	    async fn type_parameter(&self, info: &TypeInfo) -> Result<PropType, CallError> {
350	        if info.is_this_type {
351	            return Ok(named("this".to_string(), Vec::new()));
352	        }
353	        let name = match self.rpc.symbol_of_type(info.id).await? {
354	            Some(symbol) => symbol.name,
355	            None => self.display(info.id).await?,
356	        };
