360	    async fn literal(&self, info: &TypeInfo) -> Result<PropType, CallError> {
361	        let flags = info.flags;
362	        let value = info.value.as_ref();
363	        let known = if flags & flag::BIG_INT_LITERAL != 0 {
364	            value.and_then(|value| value.as_str()).and_then(BigIntValue::parse).map(PropType::BigIntLiteral)
365	        } else if flags & flag::STRING_LITERAL != 0 {
366	            value.and_then(|value| value.as_str()).map(|text| PropType::StringLiteral(text.to_string()))
367	        } else {
368	            value.and_then(|value| value.as_f64()).map(PropType::NumberLiteral)
369	        };
370	        let Some(literal) = known else { return Ok(named(self.display(info.id).await?, Vec::new())) };
371	        if flags & flag::ENUM_LITERAL == 0 {
372	            return Ok(literal);
373	        }
374	        // A member of an enum is its value and keeps the enum's name.
375	        let Some(member) = self.rpc.symbol_of_type(info.id).await? else { return Ok(literal) };
376	        let Some(parent) = self.rpc.parent_of_symbol(&member.reference).await? else { return Ok(literal) };
377	        let value = match literal {
378	            PropType::StringLiteral(text) => EnumMemberValue::String(text),
379	            PropType::NumberLiteral(number) => EnumMemberValue::Number(number),
380	            other => return Ok(other),
381	        };
382	        Ok(PropType::EnumMember { enum_name: parent.name.into(), member: member.name.into(), value })
383	    }
