385	    /// The beta's responses carry neither `value` nor, in some builds, `intrinsicName` for `true` and `false`.
386	    async fn boolean_value(&self, info: &TypeInfo) -> Result<bool, CallError> {
387	        if let Some(name) = info.intrinsic_name.as_deref() {
388	            return Ok(name == "true");
389	        }
390	        if let Some(value) = info.value.as_ref().and_then(|value| value.as_bool()) {
391	            return Ok(value);
392	        }
393	        Ok(self.display(info.id).await? == "true")
