396	    async fn template(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
397	        let origin = self.alias_origin(info).await?;
398	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
399	        let (holes, inner) = match gate {
400	            Gate::Stop(stopped) => return Ok(stopped),
401	            Gate::Open { parts, inner } => (parts, inner),
402	        };
403	        let mut types = self.convert_all(&holes, &inner).await?.into_iter();
404	        let mut parts = Vec::new();
405	        for text in &info.texts {
406	            if !text.is_empty() {
407	                parts.push(TemplatePart::Text(text.clone()));
408	            }
409	            if let Some(hole) = types.next() {
410	                parts.push(TemplatePart::Type(hole));
411	            }
412	        }
413	        Ok(PropType::TemplateLiteral(parts))
414	    }
