437	    /// appends to a class or interface).
438	    async fn type_arguments_of(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<Vec<PropType>, CallError> {
439	        let arguments = if origin.alias {
440	            if info.alias_type_arguments.is_empty() {
441	                Vec::new()
442	            } else {
443	                self.rpc.alias_type_arguments(info.id).await?
444	            }
445	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
446	            let mut arguments = self.rpc.type_arguments(info.id).await?;
447	            while arguments.last().is_some_and(|argument| argument.is_this_type) {
448	                arguments.pop();
449	            }
450	            arguments
451	        } else {
452	            Vec::new()
453	        };
454	        self.convert_all(&arguments, &cx.argument()).await
455	    }
