462	    /// The one gate every descent into the parts of a type passes, before the parts are converted. It stops, in this
463	    /// order, a type that is an instantiation already being expanded around it (a back-reference to its declaration,
464	    /// whose arguments are the instantiation's), a type past [`MAX_DEPTH`], and a type whose `measure`d parts exceed the
465	    /// `limits`. `measure` fetches the parts and says how many there are; it is not called for a type stopped before.
466	    /// Otherwise the parts come back with the context to convert them in.
467	    async fn enter<T, F, Fut>(
468	        &self,
469	        info: &TypeInfo,
470	        origin: Option<&Origin>,
471	        cx: &Cx,
472	        limits: [usize; 2],
473	        measure: F,
474	    ) -> Result<Gate<T>, CallError>
475	    where
476	        T: Send,
477	        F: FnOnce() -> Fut + Send,
478	        Fut: Future<Output = Result<(T, usize), CallError>> + Send,
479	    {
480	        // The handle is the instantiation: `Box<string>` inside `Box<Box<string>>` is another type from the one around it.
481	        if let Some(origin) = origin
482	            && cx.encloses(info.id)
483	        {
484	            return Ok(Gate::Stop(self.recursive(info, origin, cx).await?));
485	        }
486	        if cx.depth >= MAX_DEPTH {
487	            return Ok(Gate::Stop(self.truncated(info, origin, TruncationLimit::Depth).await?));
488	        }
489	        let (parts, total) = measure().await?;
490	        if total > cx.limit(limits) {
491	            let limit = TruncationLimit::Members { total: to_u32(total) };
492	            return Ok(Gate::Stop(self.truncated(info, origin, limit).await?));
493	        }
494	        Ok(Gate::Open { parts, inner: cx.below(origin.map(|_| info.id)) })
495	    }
