497	    async fn union(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
498	        let origin = self.origin(info).await?;
499	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
500	            return Ok(terminal);
501	        }
502	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
503	        let (members, inner) = match gate {
504	            Gate::Stop(stopped) => return Ok(stopped),
505	            Gate::Open { parts, inner } => (parts, inner),
506	        };
507	        Ok(union_of(self.convert_all(&members, &inner).await?))
508	    }
