510	    /// The members of a union, intersection or template literal, and how many there are.
511	    async fn members_of(&self, info: &TypeInfo) -> Result<(Vec<TypeInfo>, usize), CallError> {
512	        let members = self.rpc.members(info.id).await?;
513	        let total = members.len();
514	        Ok((members, total))
515	    }
