517	    async fn intersection(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
518	        let origin = self.origin(info).await?;
519	        // A dependency's `Nested<Style>`-like alias is a name, as its interface would be.
520	        if let Some(origin) = &origin
521	            && origin.is_boundary()
522	        {
523	            return self.named_type(info, origin, cx).await;
524	        }
525	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
526	        let (members, inner) = match gate {
527	            Gate::Stop(stopped) => return Ok(stopped),
528	            Gate::Open { parts, inner } => (parts, inner),
529	        };
530	        let mut converted: Vec<PropType> = Vec::with_capacity(members.len());
531	        for member in self.convert_all(&members, &inner).await? {
532	            if !converted.contains(&member) {
533	                converted.push(member);
534	            }
535	        }
536	        Ok(if converted.len() == 1 { converted.swap_remove(0) } else { PropType::Intersection(converted) })
537	    }
