539	    async fn object(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
540	        if info.is_tuple_type {
541	            return self.tuple(info, cx).await;
542	        }
543	        if info.object_flags & flag::OBJECT_REFERENCE != 0
544	            && let Some(own) = self.symbol_origin(info).await?
545	            && own.in_lib()
546	            && !own.alias
547	            && matches!(own.name.as_str(), "Array" | "ReadonlyArray")
548	        {
549	            return self.array(info, own.name == "ReadonlyArray", cx).await;
550	        }
551	        let origin = self.origin(info).await?;
552	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
553	            return Ok(terminal);
554	        }
555	        let boundary = origin.as_ref().filter(|origin| origin.is_boundary());
556	        // A dependency's interface is a name unless it is callable; its properties are not asked for.
557	        if let Some(origin) = boundary
558	            && self.rpc.signatures(info.id, SignatureKind::Call).await?.is_empty()
559	        {
560	            return self.named_type(info, origin, cx).await;
561	        }
562	        let gate = self
563	            .enter(info, origin.as_ref(), cx, MAX_FIELDS, || async {
564	                let members = self.rpc.object_members(info.id).await?;
565	                // A dependency's function with properties of its own (a component, a hook) is a name, however many.
566	                let named = boundary.is_some() && !members.properties.is_empty();
567	                let total = if named { 0 } else { members.properties.len() + members.indexes.len() };
568	                Ok((members, total))
569	            })
570	            .await?;
571	        let (members, inner) = match gate {
572	            Gate::Stop(stopped) => return Ok(stopped),
573	            Gate::Open { parts, inner } => (parts, inner),
574	        };
575	        let ObjectMembers { calls, constructs, properties, indexes } = members;
576	        if let Some(origin) = boundary
577	            && !properties.is_empty()
578	        {
579	            return self.named_type(info, origin, cx).await;
580	        }
581	
582	        // Which of a signature's parameters are optional is read from the printed type here, and nowhere else.
583	        let Some(markers) = self.printed_markers(info.id, &calls, &constructs).await? else {
584	            return self.unreadable_signatures(info.id).await;
585	        };
586	        let mut signatures = Vec::with_capacity(calls.len() + constructs.len());
587	        for (kind, group, printed) in
588	            [(Kind::Call, &calls, &markers.calls), (Kind::Construct, &constructs, &markers.constructs)]
589	        {
590	            for (index, signature) in group.iter().enumerate() {
591	                let printed = printed.get(index).map(Vec::as_slice);
592	                let Some((type_params, params, return_type)) = self.signature_parts(signature, printed, &inner).await?
593	                else {
594	                    return self.unreadable_signatures(info.id).await;
595	                };
596	                signatures.push(CallSignature { kind, type_params, params, return_type });
597	            }
598	        }
599	        if signatures.len() == 1 && calls.len() == 1 && properties.is_empty() && indexes.is_empty() {
600	            let CallSignature { type_params, params, return_type, .. } = signatures.swap_remove(0);
601	            return Ok(PropType::Function { type_params, params, return_type: Box::new(return_type) });
602	        }
603	        let fields = self.fields(&properties, &indexes, &inner).await?;
604	        if signatures.is_empty() {
605	            return Ok(PropType::Object(fields));
606	        }
607	        Ok(PropType::Callable { signatures, fields })
608	    }
