610	    async fn array(&self, info: &TypeInfo, readonly: bool, cx: &Cx) -> Result<PropType, CallError> {
611	        // Only an alias can name an array that contains itself (`type Loop = Loop[]`); `Array` is the lib's.
612	        let origin = self.alias_origin(info).await?;
613	        let gate = self
614	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
615	                let arguments = self.rpc.type_arguments(info.id).await?;
616	                let total = arguments.len();
617	                Ok((arguments, total))
618	            })
619	            .await?;
620	        let (arguments, inner) = match gate {
621	            Gate::Stop(stopped) => return Ok(stopped),
622	            Gate::Open { parts, inner } => (parts, inner),
623	        };
624	        let Some(element) = arguments.first() else {
625	            return Ok(named(self.display(info.id).await?, Vec::new()));
626	        };
627	        let element = PropType::Array(Box::new(self.convert(element, &inner).await?));
628	        // `readonly T[]` is `ReadonlyArray<T>`: the same reference through another declaration.
629	        Ok(if readonly { PropType::Readonly(Box::new(element)) } else { element })
630	    }
