632	    async fn tuple(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
633	        let origin = self.alias_origin(info).await?;
634	        let gate = self
635	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
636	                // The reference carries the arguments; the tuple type it instantiates carries how each element is declared.
637	                let arguments = self.rpc.type_arguments(info.id).await?;
638	                let target = self.rpc.target_of_type(info.id).await?;
639	                let total = arguments.len();
640	                Ok(((arguments, target), total))
641	            })
642	            .await?;
643	        let ((arguments, target), inner) = match gate {
644	            Gate::Stop(stopped) => return Ok(stopped),
645	            Gate::Open { parts, inner } => (parts, inner),
646	        };
647	        let labels = if target.labeled_element_declarations.is_empty() {
648	            None
649	        } else {
650	            tuple_labels(&self.display(info.id).await?, arguments.len())
651	        };
652	        let element_types = self.convert_all(&arguments, &inner).await?;
653	        let mut elements = Vec::with_capacity(arguments.len());
654	        for (index, element_type) in element_types.into_iter().enumerate() {
655	            let element_flags = target.element_flags.get(index).copied().unwrap_or(1);
656	            let kind = if element_flags & flag::ELEMENT_VARIADIC != 0 {
657	                TupleElementKind::Variadic
658	            } else if element_flags & flag::ELEMENT_REST != 0 {
659	                TupleElementKind::Rest
660	            } else if element_flags & flag::ELEMENT_OPTIONAL != 0 {
661	                TupleElementKind::Optional
662	            } else {
663	                TupleElementKind::Required
664	            };
665	            let label = labels.as_ref().and_then(|labels| labels.get(index)).and_then(|label| TupleLabel::new(label));
666	            // An optional element's type argument includes the `undefined` of leaving it out.
667	            let element_type = without_undefined(element_type, kind == TupleElementKind::Optional);
668	            elements.push(TupleElement { element_type, kind, label });
669	        }
670	        let tuple = PropType::Tuple(elements);
671	        Ok(if target.readonly { PropType::Readonly(Box::new(tuple)) } else { tuple })
672	    }
