674	    async fn fields(
675	        &self,
676	        properties: &[SymbolInfo],
677	        indexes: &[crate::rpc::IndexInfo],
678	        cx: &Cx,
679	    ) -> Result<Vec<ObjectField>, CallError> {
680	        let references: Vec<_> = properties.iter().map(|property| &property.reference).collect();
681	        let (types, readonly) = if references.is_empty() {
682	            (Vec::new(), Vec::new())
683	        } else {
684	            (self.rpc.types_of_symbols(&references).await?, self.rpc.readonly_symbols(&references).await?)
685	        };
686	        let converted = self.convert_all(&types, cx).await?;
687	        let mut fields = Vec::with_capacity(properties.len() + indexes.len());
688	        for ((property, prop_type), readonly) in properties.iter().zip(converted).zip(readonly) {
689	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
690	            let prop_type = without_undefined(prop_type, !required);
691	            let mut field = ObjectField::new(property_name(&property.name), prop_type, required, String::new());
692	            field.readonly = readonly;
693	            fields.push(field);
694	        }
695	        let sides: Vec<TypeInfo> =
696	            indexes.iter().flat_map(|index| [index.key_type.clone(), index.value_type.clone()]).collect();
697	        let mut sides = self.convert_all(&sides, cx).await?.into_iter();
698	        for index in indexes {
699	            let (Some(key), Some(value)) = (sides.next(), sides.next()) else { break };
700	            let mut field = ObjectField::new("key", value, true, String::new());
701	            field.readonly = index.is_readonly;
702	            field.index_key = Some(Box::new(key));
703	            fields.push(field);
704	        }
705	        Ok(fields)
706	    }
