708	    /// The parameter markers of the signatures of an object type, as the checker prints the type (see
709	    /// [`crate::printed`]): the only source of which parameters are optional, since the API's parameter symbols do not
710	    /// say. `None` when some signature has a parameter and the printed type does not state one entry per signature.
711	    async fn printed_markers(
712	        &self,
713	        id: u64,
714	        calls: &[SignatureInfo],
715	        constructs: &[SignatureInfo],
716	    ) -> Result<Option<SignatureMarkers>, CallError> {
717	        if !calls.iter().chain(constructs).any(|signature| !signature.parameters.is_empty()) {
718	            let none = |count: usize| vec![Vec::new(); count];
719	            return Ok(Some(SignatureMarkers { calls: none(calls.len()), constructs: none(constructs.len()) }));
720	        }
721	        let stated = signature_markers(&self.display_expanded(id).await?);
722	        Ok(stated.filter(|stated| stated.calls.len() == calls.len() && stated.constructs.len() == constructs.len()))
723	    }
