726	    /// would assert one of them: it is opaque, with how the checker prints it.
727	    async fn unreadable_signatures(&self, id: u64) -> Result<PropType, CallError> {
728	        Ok(degraded_type(self.display_expanded(id).await?, OpaqueReason::UnsupportedExpression))
