731	    /// One signature's type parameters, parameters and return type; `None` when a parameter that is not the rest
732	    /// parameter has no marker, since whether it is optional is then unknown and is not guessed.
733	    async fn signature_parts(
734	        &self,
735	        signature: &SignatureInfo,
736	        printed: Option<&[Marker]>,
737	        cx: &Cx,
738	    ) -> Result<Option<(Vec<String>, Vec<FunctionParam>, PropType)>, CallError> {
739	        let parameters = self.rpc.parameters(signature.id).await?;
740	        let has_rest = signature.flags & flag::SIGNATURE_HAS_REST_PARAMETER != 0;
741	        // A printed signature that does not give one entry per parameter states none of them.
742	        let markers = printed.filter(|markers| markers.len() == parameters.len());
743	        let known_without_markers = usize::from(has_rest);
744	        if markers.is_none() && parameters.len() > known_without_markers {
745	            return Ok(None);
746	        }
747	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
748	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
749	        let converted = self.convert_all(&types, cx).await?;
750	        let mut params = Vec::with_capacity(parameters.len());
751	        for (index, (parameter, param_type)) in parameters.iter().zip(converted).enumerate() {
752	            let marker = markers.and_then(|markers| markers.get(index)).copied().unwrap_or_default();
753	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
754	            let optional = marker.optional && !rest;
755	            let param_type = without_undefined(param_type, optional);
756	            // A destructured parameter has no name of its own; the checker calls it `__0`.
757	            let name = (!is_destructured(&parameter.name)).then(|| parameter.name.clone());
758	            params.push(FunctionParam { name, param_type, optional, rest });
759	        }
760	        let return_info = self.rpc.return_type(signature.id).await?;
761	        let return_type = self.convert(&return_info, cx).await?;
762	        let mut type_params = Vec::new();
763	        if !signature.type_parameters.is_empty() {
764	            for parameter in self.rpc.type_parameters(signature.id).await? {
765	                match self.rpc.symbol_of_type(parameter.id).await? {
766	                    Some(symbol) => type_params.push(symbol.name),
767	                    None => type_params.push(self.display(parameter.id).await?),
768	                }
769	            }
770	        }
771	        Ok(Some((type_params, params, return_type)))
772	    }
773	}
