775	/// The checker keys a property named by a symbol `__@<name>@<symbol id>`; the source writes `[Symbol.iterator]` or
776	/// `[brand]`. The id is the checker's and does not belong in an answer.
777	fn property_name(name: &str) -> String {
778	    const WELL_KNOWN: [&str; 15] = [
779	        "iterator",
780	        "asyncIterator",
781	        "hasInstance",
782	        "isConcatSpreadable",
783	        "match",
784	        "matchAll",
785	        "replace",
786	        "search",
787	        "species",
788	        "split",
789	        "toPrimitive",
790	        "toStringTag",
791	        "unscopables",
792	        "dispose",
793	        "asyncDispose",
794	    ];
795	    let Some((symbol, _id)) = name.strip_prefix("__@").and_then(|rest| rest.rsplit_once('@')) else {
796	        return name.to_string();
797	    };
798	    if WELL_KNOWN.contains(&symbol) { format!("[Symbol.{symbol}]") } else { format!("[{symbol}]") }
799	}
800	
801	fn is_destructured(name: &str) -> bool {
802	    name.strip_prefix("__").is_some_and(|rest| !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()))
803	}
804	
805	fn to_u32(count: usize) -> u32 {
806	    u32::try_from(count).unwrap_or(u32::MAX)
807	}
808	
809	fn named(name: String, args: Vec<PropType>) -> PropType {
810	    PropType::Named { name: name.into(), args }
811	}
812	
813	/// The types whose conversion needs nothing but their flags.
814	fn simple(info: &TypeInfo) -> Option<PropType> {
815	    let flags = info.flags;
816	    // `boolean` is the union `false | true` and carries both flags.
817	    if flags & flag::BOOLEAN != 0 {
818	        return Some(PropType::Boolean);
819	    }
820	    let known = [
821	        (flag::ANY, PropType::Any),
822	        (flag::UNKNOWN, PropType::Unknown),
823	        (flag::UNDEFINED, PropType::Undefined),
824	        (flag::NULL, PropType::Null),
825	        (flag::VOID, PropType::Void),
826	        (flag::NEVER, PropType::Never),
827	        (flag::STRING, PropType::String),
828	        (flag::NUMBER, PropType::Number),
829	        (flag::BIG_INT, named("bigint".to_string(), Vec::new())),
830	        (flag::ES_SYMBOL, named("symbol".to_string(), Vec::new())),
831	        (flag::NON_PRIMITIVE, named("object".to_string(), Vec::new())),
832	    ];
833	    known.into_iter().find(|(bit, _)| flags & bit != 0).map(|(_, converted)| converted)
834	}
835	
836	/// A union of converted members: `false | true` is `boolean`, a union inside a union is flattened, a repeated member
837	/// is kept once, and a union of one is that member.
838	fn union_of(converted: Vec<PropType>) -> PropType {
839	    let mut flat = Vec::with_capacity(converted.len());
840	    for member in converted {
841	        match member {
842	            PropType::Union(inner) => flat.extend(inner),
843	            other => flat.push(other),
844	        }
845	    }
846	    let both_booleans = flat.contains(&PropType::BoolLiteral(true)) && flat.contains(&PropType::BoolLiteral(false));
847	    let mut members: Vec<PropType> = Vec::with_capacity(flat.len());
848	    for member in flat {
849	        let member = match member {
850	            PropType::BoolLiteral(_) if both_booleans => PropType::Boolean,
851	            other => other,
852	        };
853	        if !members.contains(&member) {
854	            members.push(member);
855	        }
856	    }
857	    if members.len() == 1 { members.swap_remove(0) } else { PropType::Union(members) }
858	}
859	
860	/// An optional prop's type includes `undefined`; react-docgen-typescript drops it, as does the structural result.
861	pub(crate) fn without_undefined(prop_type: PropType, optional: bool) -> PropType {
862	    match prop_type {
863	        PropType::Union(members) if optional => {
864	            let mut kept: Vec<PropType> = members.into_iter().filter(|m| *m != PropType::Undefined).collect();
865	            if kept.len() == 1 { kept.swap_remove(0) } else { PropType::Union(kept) }
866	        }
867	        other => other,
868	    }
869	}
