#[test]
fn nothing_the_checker_hands_out_by_number_is_in_the_answer() {
    let project = project(true);
    let output = structural(&project);
    let text = serde_json::to_string(&rendered(&answer(&project, &output, &Checker::Replay))).unwrap();

    // A symbol-keyed property is `[Symbol.iterator]`, not the checker's `__@iterator@<symbol id>`.
    assert!(!text.contains("__@"), "{text}");
    assert!(text.contains("[Symbol.iterator]"));
}

fn field(name: &str, prop_type: Value) -> Value {
    json!({ "name": name, "propType": prop_type, "required": true, "description": "" })
}

fn recursive(name: &str, args: Vec<Value>) -> Value {
    json!({ "kind": "recursive", "name": name, "args": args })
}

/// The type at a JSON pointer inside a prop's type.
fn within(value: &Value, pointer: &str) -> Value {
    value.pointer(pointer).unwrap_or_else(|| panic!("{pointer} is in {value}")).clone()
}

/// The answer replayed, and when `TSRS_BIN` names a real `tsrs` asked first to last and last to first.
fn answers(check: impl Fn(&Value)) {
    let replayed = project(true);
    let output = structural(&replayed);
    check(&rendered(&answer(&replayed, &output, &Checker::Replay)));

    let Some(bin) = tsrs_bin() else { return };
    let real = project(false);
    let output = structural(&real);
    for reverse in [false, true] {
        check(&rendered(&answer(&real, &output, &Checker::Real { bin: bin.clone(), reverse })));
    }
}

/// An alias of an array or a tuple of itself is a cycle of types with no object in between: the conversion has to end
/// at the first lap, with the reference back to the alias, whichever way round the checker is asked.
#[test]
fn a_type_that_contains_itself_through_an_array_or_a_tuple_ends_in_a_back_reference() {
    answers(|rendered| {
        let looped = recursive("LoopArray", vec![]);
        assert_eq!(prop_type(rendered, "Instances", "loopArray"), json!({ "kind": "array", "element": looped }));
        let tuple = prop_type(rendered, "Instances", "loopTuple");
        assert_eq!(within(&tuple, "/elements/0/type"), recursive("LoopTuple", vec![]));
        let readonly = prop_type(rendered, "Instances", "readonlyLoop");
        assert_eq!(within(&readonly, "/element/element"), recursive("ReadonlyLoop", vec![]));
    });
}

/// A back-reference is to a type that encloses this one: `Box<string>` inside `Box<Box<string>>` is another
/// instantiation of the declaration, finite, and stays an object. The reference keeps the declaration's name.
#[test]
fn an_instantiation_is_not_its_declaration() {
    answers(|rendered| {
        let string = json!({ "kind": "string" });
        let point = json!({ "kind": "object", "fields": [field("x", json!({ "kind": "number" }))] });
        let pair = |first: Value, second: Value| json!({ "kind": "object", "fields": [field("first", first), field("second", second)] });
        let boxed = |inner: Value| json!({ "kind": "object", "fields": [field("value", inner)] });

        assert_eq!(prop_type(rendered, "Instances", "boxed"), boxed(boxed(string.clone())));
        assert_eq!(prop_type(rendered, "Instances", "twice"), pair(point.clone(), point.clone()));
        assert_eq!(prop_type(rendered, "Instances", "nestedPair"), pair(pair(point.clone(), point.clone()), point));

        // The same instantiation inside itself is a back-reference, with the arguments of the instantiation.
        let tree = prop_type(rendered, "Instances", "tree");
        assert_eq!(within(&tree, "/fields/1/propType/element"), recursive("Tree", vec![string]));
        let mutual = prop_type(rendered, "Instances", "mutual");
        assert_eq!(
            within(&mutual, "/fields/0/propType/fields/0/propType"),
            recursive("Ping", vec![json!({ "kind": "number" })])
        );

        // A generic that names a new instantiation each time is never the same type again: the depth cap ends it, and
        // nothing is a back-reference.
        let grow = serde_json::to_string(&prop_type(rendered, "Instances", "grow")).unwrap();
        assert!(grow.contains(r#""limit":{"type":"depth"}"#) && !grow.contains("recursive"), "{grow}");
    });
}

/// Every cap fires where it says it does, with its limit and, for a width, how many there were.
#[test]
fn every_cap_cuts_where_it_is_set() {
    let project = project(true);
    let output = structural(&project);
    let rendered = rendered(&answer(&project, &output, &Checker::Replay));
    let cut = |component: &str, prop: &str, pointer: &str| {
        let ty = within(&prop_type(&rendered, component, prop), pointer);
        assert_eq!(ty["kind"], "truncated", "{component}.{prop}{pointer}: {ty}");
        ty["limit"].clone()
    };
    let members = |total: u32| json!({ "type": "members", "total": total });
    let depth = json!({ "type": "depth" });

    // Fields: 100 at the top of a prop's type, 40 below it.
    assert_eq!(cut("Caps", "wideTop", ""), members(101));
    assert_eq!(cut("Caps", "wide", "/fields/0/propType"), members(42));
    // Members, at the top (500) and below (120), of a union, an intersection and a tuple.
    assert_eq!(cut("Caps", "many", ""), members(600));
    assert_eq!(cut("Caps", "nestedMany", "/fields/0/propType"), members(200));
    assert_eq!(cut("Caps", "allOf", ""), members(501));
    assert_eq!(cut("Caps", "nestedAllOf", "/fields/0/propType"), members(121));
    assert_eq!(cut("Caps", "longTuple", ""), members(501));
    assert_eq!(cut("Caps", "nestedTuple", "/fields/0/propType"), members(121));
    // Below its limit a union is listed whole.
    assert_eq!(within(&prop_type(&rendered, "Caps", "withinLimits"), "/fields/0/propType/kind"), "union");

    // Depth 5: an object, and each other kind of type that has parts, but not a type without any.
    let below_four_objects = "/fields/0/propType".repeat(5);
    assert_eq!(cut("Caps", "deep", &below_four_objects), depth);
    for prop in ["union", "intersection", "array", "tuple", "template"] {
        assert_eq!(cut("DeepKinds", prop, &below_four_objects), depth, "{prop}");
    }
    assert_eq!(within(&prop_type(&rendered, "DeepKinds", "scalar"), &format!("{below_four_objects}/kind")), "string");
}
    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
    pub tsconfig: Option<Utf8PathBuf>,
    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
    pub tsc_path: Option<Utf8PathBuf>,
    /// The components to ask about.
    pub targets: Vec<Target>,
    /// Bound on each request, and on the `tsc` start-up handshake.
    pub request_timeout: Duration,
    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
    pub expected_versions: &'static [&'static str],
    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
    pub record_to: Option<Utf8PathBuf>,
    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
    pub extra_env: Vec<(String, String)>,
    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
    pub reverse_queries: bool,
    /// Compiler options of a `tsc` session that is already initialized. A warm checker sets this once so a request
    /// only builds its program.
    pub(crate) prepared_options: Option<serde_json::Value>,
}

impl SemanticRequest {
    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
    /// tsconfig or explicit `tsc` path.
    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
        Self {
            project_root,
            tsconfig: None,
            tsc_path: None,
            targets,
            request_timeout: Duration::from_secs(60),
            expected_versions: SUPPORTED_VERSIONS,
            record_to: None,
            extra_env: Vec::new(),
            reverse_queries: false,
            prepared_options: None,
        }
    }
}

/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
/// not be called from inside one.
pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
        Ok(runtime) => runtime,
        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
    };
    runtime.block_on(run(request))
}

    let started = std::time::Instant::now();
    let opened = match &request.prepared_options {
        Some(options) => {
            Rpc::open_with(supervisor.client(), request.request_timeout, options, files, request.record_to.is_some())
                .await
        }
        None => {
            Rpc::open(
                supervisor.client(),
                request.request_timeout,
                request.tsconfig.as_ref().map(|path| path.as_str()),
                files,
                request.record_to.is_some(),
            )
            .await
        }
    };
    let rpc = Arc::new(opened?);
    let opened = started.elapsed();
    let converter = Converter::new(rpc.clone(), request.reverse_queries);
    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
    let interner = Arc::new(PropInterner::default());

    let mut tasks = JoinSet::new();
    for file in order {
        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
        tasks.spawn(async move {
            let _permit = limit.acquire().await;
            answer_file(&rpc, &converter, &interner, targets).await
        });
    }

    let mut outcome = SemanticOutcome::default();
    let mut failure = None;
    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok(mut answered)) => {
                outcome.components.append(&mut answered.components);
                outcome.fallbacks.append(&mut answered.fallbacks);
            }
            Ok(Err(error)) => {
                failure = Some(error);
                tasks.abort_all();
            }
            // A panic inside a worker must not silently leave its components structural.
            Err(joined) if joined.is_panic() => {
                failure = Some(CallError::Fatal("a worker panicked".to_string()));
                tasks.abort_all();
            }
            // A cancelled task is one this loop aborted after a failure.
            Err(_cancelled) => {}
        }
    }
    if let Some(error) = failure {
        return Err(error);
    }

    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
        && let Ok(json) = serde_json::to_string_pretty(&recording)
        && let Err(error) = std::fs::write(path, json)
    {
        tracing::warn!("could not write the recording to {path}: {error}");
    }
    tracing::debug!(
        requests = ?rpc.calls(),
        files = files.len(),
        type_memo = ?converter.memo_stats(),
        program_ms = opened.as_millis() as u64,
        total_ms = started.elapsed().as_millis() as u64,
        "semantic backend finished"
    );
    rpc.release().await;
    outcome.components.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
    outcome.fallbacks.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
    Ok(outcome)
}

fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
    SemanticFallback {
        file_path: target.file_path.clone(),
        display_name: target.display_name.clone(),
        reason: reason.to_string(),
    }
}

/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result.
async fn answer_file(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    targets: Vec<Target>,
) -> Result<SemanticOutcome, CallError> {
    let mut outcome = SemanticOutcome::default();
    let Some(first) = targets.first() else { return Ok(outcome) };
    let exports = match module_exports(rpc, first.file_path.as_str()).await {
        Ok(Some(exports)) => exports,
        Ok(None) | Err(CallError::Rejected(_)) => {
            outcome
                .fallbacks
                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));

